package android.content;import android.os.Bundle;public class Intent {public static final int FLAG_ACTIVITY_SINGLE_TOP=0x20000000;String action; Bundle extras=new Bundle();public Intent(){}public Intent(Context c,Class<?> clazz){}public Intent setAction(String s){action=s;return this;}public String getAction(){return action;}public Intent putExtra(String k,String v){extras.putString(k,v);return this;}public int getIntExtra(String k,int d){Object o=extras.get(k);return o instanceof Number?((Number)o).intValue():d;}public boolean getBooleanExtra(String k,boolean d){Object o=extras.get(k);return o instanceof Boolean?(Boolean)o:d;}public Intent putExtra(String k,boolean v){extras.putBoolean(k,v);return this;}public String getStringExtra(String k){Object o=extras.get(k);return o==null?null:String.valueOf(o);}public Intent putExtra(String k,int v){extras.putInt(k,v);return this;}public Bundle getExtras(){return extras;}public Intent setFlags(int x){return this;}}